"""Reviewed Java graph API criteria; fixed independently of current verdicts.

Each fixture supplies authored input, expected declarations/edges and bounded
zero/one/full stopping conditions. Retained populations include guards and
unsupported obligations, never a query selecting passing children.
"""
from pathlib import Path
import re
from common import stable_id


def cli_surface():
    source = (Path(__file__).resolve().parents[2] / 'src/main.rs').read_text()
    bodies = [re.split(r'(?:struct|enum) ' + name + r' \{', source, maxsplit=1)[1].split('\n}', 1)[0]
              for name in ('Cli', 'GraphSymbolArgs', 'GraphAction')]
    return stable_id([re.sub(r'\s+', '', re.sub(r'^\s*//[^\n]*', '', body, flags=re.MULTILINE))
                      for body in bodies])


def criteria():
    return [dict(feature=f, subject=s, samples_count=n, sample_keys_sha256=k,
                 population_sha256=p, fixture=m + '.exercise',
                 production='src/commands/graph/{mod,resolve,java}.rs and src/parsers/treesitter/java.rs',
                 contract=c) for f, s, n, k, p, m, c in RETAINED]


